paths={'arrow':'<path d="M5 12h14M13 6l6 6-6 6"/>','gem':'<path d="m3 8 4-5h10l4 5-9 13Z M3 8h18M7 3l5 18 5-18"/>','phone':'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>','wallet':'<path d="M20 7H4V5l14-3v5M4 7v13h17V7Z M21 12h-7v5h7"/>','tool':'<path d="m14 5 5-3a6 6 0 0 1-7 8L4 20l-3-3 10-8a6 6 0 0 1 8-7l-4 4Z"/>','pin':'<path d="M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 1 1 14 0Z"/><circle cx="12" cy="9" r="2"/>','star':'<path d="m12 2 2.7 6.3 6.8.7-5.2 4.5 1.6 6.5-5.9-3.5-5.9 3.5 1.6-6.5L2.5 9l6.8-.7Z"/>','coin':'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="6"/><path d="M10 9h4l-4 6h4"/>','check':'<path d="m5 12 5 5L20 6"/>'}
def icon(n='arrow'):return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+paths[n]+'</svg>'
def img(src,alt,cls=''):return f'<img class="{cls}" src="{A}{src}" alt="{alt}">'
def link(text,href,cls='btn'):return f'<a class="{cls}" href="{href}">{text}{icon()}</a>'
def button(text,key,cls='btn'):return f'<button class="{cls}" type="button" data-open="{key}">{text}{icon()}</button>'
def burst():return '<svg class="burst" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 1 14.5 6.5 20 4 17.5 9.5 23 12 17.5 14.5 20 20 14.5 17.5 12 23 9.5 17.5 4 20 6.5 14.5 1 12 6.5 9.5 4 4 9.5 6.5Z"/></svg>'
def brand():return '<a class="brand" href="#main" aria-label="SEZAM — początek"><span class="brand-symbol">'+burst()+'</span>sezam<span class="brand-dot">.</span></a>'
def contact(cls=''):return f'''<section id="kontakt" class="contact {cls}"><div><span class="kicker">DOBRZE SIĘ SPOTKAĆ</span><h2>Gorzów. <br>Pocztowa 11.</h2></div><div class="contact-details"><a class="contact-phone" href="tel:+48601775146">601 775 146 {icon()}</a><div class="contact-hours"><span>Poniedziałek–piątek <b>10:00–18:00</b></span><span>Sobota <b>10:00–14:00</b></span><small>Niedziela — zamknięte. Godziny w święta potwierdź telefonicznie.</small></div><div class="contact-actions">{link('WhatsApp','https://wa.me/48601775146','btn ghost')}{link('Wyznacz trasę','https://www.google.com/maps/dir/?api=1&destination=Pocztowa+11+Gorz%C3%B3w+Wielkopolski','text-link')}</div></div></section>'''
def calc():return '''<form class="calc-form" data-calc><div class="calc-inputs"><label>Kwota pożyczki, zł<input type="number" name="amount" min="50" max="100000" step="50" value="2000" required></label><label>Okres<select name="days"><option value="15">15 dni · 2,5%</option><option value="30">30 dni · 5%</option></select></label></div><div class="calc-presets">'''+''.join(f'<button type="button" data-amount="{n}" aria-pressed="false">{n:,} zł</button>'.replace(',',' ') for n in [500,1000,2000,5000,10000])+'''</div><div class="calc-numbers" aria-live="polite"><div><span>Opłata</span><strong class="fee">50,00 zł</strong></div><div><span>Łącznie do spłaty</span><strong class="total">2050,00 zł</strong></div></div><p class="calc-error" hidden>Podaj kwotę od 50 do 100 000 zł.</p><a class="btn calc-contact" href="https://wa.me/48601775146" target="_blank" rel="noopener">Zapytaj o pożyczkę →</a><p class="calc-note">Obliczenie orientacyjne według tabeli SEZAM dla 15 i 30 dni. Dokładny koszt i termin potwierdzamy przed podpisaniem umowy. Przy wyższych kwotach warunki ustalamy indywidualnie.</p></form>'''
